package com.lightboard.keyboard;

import static org.junit.Assert.*;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

public class LangDetectTest {
    private static List<String> w(String s) { return Arrays.asList(s.split(" ")); }

    @Test public void detects_en() { assertEquals("en", LangDetect.detect(w("the of and to in is you that it he was for on are with as his they at be this have from or one had by word but not what all were we when your can said there use an each which she do how their if will up other about out many then them these so some her would make like him into time has look two more write go see no way could people my than first water been call who oil its now find long down day did get come made may part"))); }
    @Test public void detects_de() { assertEquals("de", LangDetect.detect(w("der die und in den von zu das mit sich des auf f\u00fcr ist im dem nicht ein eine als auch es an werden aus er hat dass sie nach wird bei einer um am sind noch wie einem \u00fcber einen so zum war haben nur oder aber vor zur bis mehr durch man sein wurde sei ich du sch\u00f6n gr\u00fc\u00dfe"))); }
    @Test public void detects_fr() { assertEquals("fr", LangDetect.detect(w("de la le et les des en un du une que est pour qui dans a par plus pas au sur ne se ce il sont ou avec son je vous nous mais comme on tout elle y aux cette fait \u00eatre \u00e9t\u00e9 leur sans ces entre caf\u00e9 tr\u00e8s"))); }
    @Test public void detects_es() { assertEquals("es", LangDetect.detect(w("de la que el en y a los se del las un por con no una su para es al lo como m\u00e1s pero sus le ya o este s\u00ed porque esta entre cuando muy sin sobre tambi\u00e9n me hasta hay donde quien desde todo nos durante a\u00f1o ni\u00f1o"))); }
    @Test public void detects_ru() { assertEquals("ru", LangDetect.detect(w("\u0438 \u0432 \u043d\u0435 \u043d\u0430 \u044f \u0447\u0442\u043e \u043e\u043d \u0441 \u043a\u0430\u043a \u0430 \u044d\u0442\u043e \u043f\u043e \u043d\u043e \u043e\u043d\u0438 \u043c\u044b \u0432\u044b \u043e\u043d\u0430 \u0435\u0433\u043e \u043a \u0443 \u0436\u0435 \u0437\u0430 \u0438\u0437 \u043e\u0442 \u0442\u043e \u0432\u0441\u0435 \u0442\u0430\u043a \u0435\u0433\u043e \u0442\u043e\u043b\u044c\u043a\u043e \u0431\u044b\u043b\u043e \u0431\u044b \u0435\u0449\u0451 \u0434\u043b\u044f \u043c\u043d\u0435 \u0443\u0436\u0435 \u0432\u043e\u0442 \u043a\u043e\u0433\u0434\u0430 \u0435\u0441\u043b\u0438 \u0434\u0430\u0436\u0435 \u0442\u0435\u0431\u044f \u043d\u0435\u0442 \u0434\u0430 \u043d\u0443"))); }
    @Test public void detects_uk() { assertEquals("uk", LangDetect.detect(w("\u0456 \u0432 \u043d\u0435 \u043d\u0430 \u044f \u0449\u043e \u0432\u0456\u043d \u0437 \u044f\u043a \u0430 \u0446\u0435 \u043f\u043e \u0430\u043b\u0435 \u0432\u043e\u043d\u0438 \u043c\u0438 \u0432\u0438 \u0432\u043e\u043d\u0430 \u0439\u043e\u0433\u043e \u0434\u043e \u0443 \u0436\u0435 \u0437\u0430 \u0456\u0437 \u0432\u0456\u0434 \u0442\u043e \u0432\u0441\u0435 \u0442\u0430\u043a \u0442\u0456\u043b\u044c\u043a\u0438 \u0431\u0443\u043b\u043e \u0431 \u0449\u0435 \u0434\u043b\u044f \u043c\u0435\u043d\u0456 \u0432\u0436\u0435 \u043e\u0441\u044c \u043a\u043e\u043b\u0438 \u044f\u043a\u0449\u043e \u043d\u0430\u0432\u0456\u0442\u044c \u0442\u0435\u0431\u0435 \u043d\u0456 \u0442\u0430\u043a \u043d\u0443 \u0457\u0445 \u0454 \u0491\u0430\u043d\u043e\u043a"))); }
    @Test public void detects_el() { assertEquals("el", LangDetect.detect(w("\u03ba\u03b1\u03b9 \u03bd\u03b1 \u03c4\u03bf \u03b7 \u03bf \u03c4\u03b7\u03c2 \u03c0\u03bf\u03c5 \u03c4\u03b1 \u03bc\u03b5 \u03c4\u03bf\u03c5 \u03b3\u03b9\u03b1 \u03b4\u03b5\u03bd \u03c4\u03b7\u03bd \u03c3\u03c4\u03bf \u03ad\u03bd\u03b1 \u03c3\u03c4\u03b7 \u03b1\u03c0\u03cc \u03bf\u03b9 \u03b8\u03b1 \u03c4\u03c9\u03bd \u03cc\u03c4\u03b9 \u03b5\u03af\u03bd\u03b1\u03b9 \u03c3\u03b5 \u03bc\u03b9\u03b1 \u03b1\u03c5\u03c4\u03cc \u03c0\u03b9\u03bf \u03ae\u03c4\u03b1\u03bd \u03c4\u03bf\u03bd \u03bc\u03bf\u03c5 \u03c3\u03bf\u03c5 \u03ba\u03b9 \u03ac\u03bb\u03bb\u03bf \u03cc\u03c4\u03b1\u03bd \u03b5\u03b4\u03ce"))); }
    @Test public void detects_fa() { assertEquals("fa", LangDetect.detect(w("\u06a9\u0647 \u0627\u06cc\u0646 \u0631\u0627 \u0628\u0627 \u0627\u0633\u062a \u062f\u0631 \u0628\u0647 \u0627\u0632 \u0645\u0646 \u062a\u0648 \u0627\u0648 \u0645\u0627 \u0634\u0645\u0627 \u0622\u0646\u0647\u0627 \u06cc\u06a9 \u0628\u0631\u0627\u06cc \u067e\u06cc\u0634 \u0686\u0647 \u0686\u06cc \u0646\u0647 \u0647\u0645 \u06a9\u0627\u0631 \u06af\u0641\u062a \u06a9\u0631\u062f \u0628\u0648\u062f \u0645\u06cc \u062e\u0648\u062f \u0627\u06af\u0631 \u0647\u0645\u0647 \u0647\u0631 \u0627\u06cc\u0631\u0627\u0646 \u06af\u0641\u062a\u06af\u0648"))); }
    @Test public void tooFewWordsGivesNull() { assertNull(LangDetect.detect(w("the of and"))); }
}
